            yield return Key(input,0x77);yield return Key(input,0x77);Check(shell.SetupLibraryOpen&&shell.Root.Q<Label>("setupPreviewTitle").text=="Café sprint","F8 preserves the selected renamed blueprint");yield return Capture("setup-managed-name");
