            normalized=EngineWorkshop.Copy(game.Profile);normalized.revision=revision;normalized.savedSetups.Insert(index,removed);Check(SnapshotEquality.Profile(before,normalized,game.Profile.catalog)&&game.DraftDirty&&draft==JsonUtility.ToJson(game.DraftValues)&&cart==JsonUtility.ToJson(new PartCart.Lines{entries=game.CartLines.Select(l=>l.Copy()).ToList()}),"Delete keeps all cars, worn parts, fluids, money, tuning drafts and cart lines");Check(!ProfileStore.Load().savedSetups.Any(s=>s.id==id),"Deletion survives SQLite reload");yield return Capture("setup-deleted");
            game.ClearNativeCart();Check(game.ApplyTuneDraftNow(),"Preserved tuning draft still applies against its rebased revision");yield return new WaitForSecondsRealtime(.3f);yield return Click(input,"setupCard:"+other);yield return Click(input,"setupLoad");yield return Click(input,"setupLoadConfirm");Check(!shell.ModalOpen&&game.Profile.savedSetups.Any(s=>s.id==other)&&game.Profile.SelectedCar.tune.driverMassKg==game.Profile.savedSetups.Single(s=>s.id==other).tune.driverMassKg,"Remaining saved setup still loads through the established confirmation workflow");
